let raw = $input.first().json.output;

// Cek apakah output adalah nested Communication_Agent_response
if (raw.includes('Communication_Agent_response')) {
  const outer = JSON.parse(raw);
  const content = JSON.parse(outer.Communication_Agent_response.content);
  raw = content[0].output;
}

// Strip markdown code block jika ada
raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();

const output = JSON.parse(raw);
const token = $('Main Webhook').first().json.body.google_access_token;

const rawEmail = [
  'To: ' + output.to,
  'Subject: ' + output.subject,
  'Content-Type: text/html; charset=utf-8',
  '',
  output.message
].join('\r\n');

const encoded = Buffer.from(rawEmail)
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/, '');

return [{
  json: {
    raw: encoded,
    to: output.to,
    subject: output.subject,
    token: token
  }
}];

const rawOutput = $input.first().json.output;

const unwrapAgentOutput = (value) => {
  let current = value;
  for (let i = 0; i < 3; i += 1) {
    if (Array.isArray(current) && current[0]?.output !== undefined) {
      current = current[0].output;
      continue;
    }

    if (current && typeof current === 'object' && current.output !== undefined) {
      current = current.output;
      continue;
    }

    if (typeof current === 'string') {
      const trimmed = current.trim();
      if ((trimmed.startsWith('[') || trimmed.startsWith('{')) && trimmed.includes('"output"')) {
        try {
          current = JSON.parse(trimmed);
          continue;
        } catch (error) {}
      }
    }

    break;
  }

  return String(current || '');
};

const output = unwrapAgentOutput(rawOutput);
const cleaned = output
  .replace(/^[\s\S]*?(?=<section)/i, '')
  .replace(/```html/gi, '')
  .replace(/```/g, '')
  .replace(/Presentasi Anda sudah siap.*/gs, '')
  .replace(/\\n/g, ' ')
  .replace(/\n/g, ' ')
  .trim();

const decodeHtml = (value) => String(value || '')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>');

const stripTags = (value) => decodeHtml(String(value || '').replace(/<[^>]+>/g, ' '))
  .replace(/\\n/g, ' ')
  .replace(/\b[nN]\b/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const normalizeTitle = (value) => String(value || '')
  .replace(/\\n/g, ' ')
  .replace(/\b[nN]\b/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const splitSectionByH1 = (body) => {
  const h1Regex = /<h1\b[^>]*>[\s\S]*?<\/h1>/gi;
  const h1Matches = [...body.matchAll(h1Regex)];
  if (h1Matches.length <= 1) return [`<section class="slide">${body.trim()}</section>`];
  const slides = [];
  for (let i = 0; i < h1Matches.length; i += 1) {
    const start = h1Matches[i].index ?? 0;
    const end = i + 1 < h1Matches.length ? (h1Matches[i + 1].index ?? body.length) : body.length;
    const chunk = body.slice(start, end).trim();
    if (chunk) slides.push(`<section class="slide">${chunk}</section>`);
  }
  return slides.length ? slides : [`<section class="slide">${body.trim()}</section>`];
};

const sectionRegex = /<section[^>]*class=["'][^"']*slide[^"']*["'][^>]*>([\s\S]*?)<\/section>/gi;
const normalizedSections = [];
let match;
while ((match = sectionRegex.exec(cleaned)) !== null) {
  const body = match[1] || '';
  normalizedSections.push(...splitSectionByH1(body));
}

const slideMarkup = normalizedSections.length ? normalizedSections : ['<section class="slide">' + cleaned + '</section>'];
const wrappedPages = slideMarkup.map((section) => `<div class="pdf-page">${section}</div>`).join('\n');

const pickTitle = (html) => {
  const h1 = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i)?.[1];
  if (h1) return stripTags(h1);
  const h2 = html.match(/<h2[^>]*>([\s\S]*?)<\/h2>/i)?.[1];
  if (h2) return stripTags(h2);
  const section = html.match(/<section[^>]*>([\s\S]*?)<\/section>/i)?.[1] || html;
  const plain = stripTags(section);
  return plain.split(/(?<=[.!?])\s+/)[0] || plain;
};

const titleSource = normalizeTitle(pickTitle(wrappedPages) || $('Main Webhook').first().json.body.message || 'Presentasi');
const compactTitle = titleSource.split(/\s+/).slice(0, 8).join(' ').trim() || 'Presentasi';
const slug = compactTitle.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^A-Za-z0-9]+/g, '-').replace(/^-+|-+$/g, '').replace(/-+/g, '-');
const timestamp = $now.setZone('Asia/Jakarta').toFormat('yyyy-MM-dd_HH-mm');
const nama_file_laporan = (slug || 'Presentasi') + '_' + timestamp + '.pdf';

return [{ json: { output: wrappedPages, nama_file_laporan, presentation_title: compactTitle } }];

function convertMarkdownTableToHtml(markdown) {
    // Regex untuk detect markdown table
    const tableRegex = /(\|.+\|[\r\n]+\|[-:\s|]+\|[\r\n]+(?:\|.+\|[\r\n]*)+)/g;

    return markdown.replace(tableRegex, (match) => {
      const lines = match.trim().split('\n').map(line =>
        line.trim().split('|').filter(cell => cell.trim())
      );

      if (lines.length < 3) return match; // Not a valid table

      const headers = lines[0];
      const rows = lines.slice(2); // Skip separator line

      let html = '<table border="1" style="border-collapse: collapse; width: 100%;">\n';

      // Header
      html += '  <thead>\n    <tr>\n';
      headers.forEach(header => {
        html += `      <th style="padding: 8px; text-align: left; background-color: #f2f2f2;">${header.trim()}</th>\n`;
      });
      html += '    </tr>\n  </thead>\n';

      // Body
      html += '  <tbody>\n';
      rows.forEach(row => {
        html += '    <tr>\n';
        row.forEach(cell => {
          html += `      <td style="padding: 8px; border: 1px solid #ddd;">${cell.trim()}</td>\n`;
        });
        html += '    </tr>\n';
      });
      html += '  </tbody>\n</table>\n';

      return html;
    });
  }

  const markdown = $input.first().json.output;
  const processedMarkdown = convertMarkdownTableToHtml(markdown);

  return [{ json: { output: processedMarkdown } }];

