// This node normalizes supervisor pass-through so downstream routing sees
// the original specialist output instead of a paraphrased wrapper.
// It also recovers mistaken pass-through email-send templates
// into the JSON shape expected by Route Output Type.

const inputJson = $input.first().json;
const supervisorOutput = String(inputJson.output || '');
const getOriginalPrompt = () => {
  try {
    return $('Set - Prompt From User').first().json?.PromptFinal || '';
  } catch (error) {
    return '';
  }
};

const originalPrompt = getOriginalPrompt();

const parseSendTemplate = (text) => {
  if (typeof text !== 'string' || !/KIRIMKAN\s+SEKARANG/i.test(text)) {
    return null;
  }

  const normalized = text.replace(/\r/g, '').trim();
  const match = normalized.match(/KIRIMKAN\s+SEKARANG\s+email\s+lengkap\s+dibawah\s+ini\s+ke\s+alamat:\s*([^\n]+)\n+---\n*SUBJECT:\s*([^\n]+)\n+([\s\S]+?)\n*---\s*$/i);

  if (!match) {
    return null;
  }

  return {
    action: 'send',
    to: match[1].trim(),
    subject: match[2].trim(),
    message: match[3].trim(),
  };
};

const recoveredSend = parseSendTemplate(supervisorOutput) || parseSendTemplate(originalPrompt);
if (recoveredSend) {
  return [{
    json: {
      ...inputJson,
      output: JSON.stringify(recoveredSend),
      _recovered_send: true,
    },
  }];
}

const extractStepOutput = (value) => {
  let current = value;
  for (let i = 0; i < 3; i += 1) {
    if (Array.isArray(current) && current[0]?.output !== undefined) {
      current = current[0].output;
      continue;
    }
    if (current && typeof current === 'object' && current.output !== undefined) {
      current = current.output;
      continue;
    }
    if (typeof current === 'string') {
      const trimmed = current.trim();
      if ((trimmed.startsWith('[') || trimmed.startsWith('{')) && trimmed.includes('\"output\"')) {
        try {
          current = JSON.parse(trimmed);
          continue;
        } catch (error) {}
      }
    }
    break;
  }
  return String(current || '');
};

const pickDocumentObservation = () => {
  const steps = inputJson.intermediateSteps || [];
  for (const step of steps) {
    const observation = extractStepOutput(step?.observation || step?.output || '');
    if (!observation) continue;

    const hasPresentationMarkup = /<section\b[^>]*class=[\"'][^\"']*slide/i.test(observation);
    const hasDocumentSignal = observation.includes('Unduh Dokumen (PDF)') || observation.includes('Unduh Presentasi (PDF)');
    const isSubstantial = observation.length > 120;

    if ((hasPresentationMarkup || hasDocumentSignal) && isSubstantial) {
      return observation.trim();
    }
  }
  return '';
};

const documentObservation = pickDocumentObservation();
const trimmedSupervisor = supervisorOutput.trim();
const hasHTML = /<(section|div)\b/i.test(supervisorOutput) || supervisorOutput.includes('```html');
const startsWithDocumentMarkup = /^(<section\b|<div\b|```html)/i.test(trimmedSupervisor);
const isPPTSignal = supervisorOutput.includes('Unduh Presentasi (PDF)');
const isPDFSignal = supervisorOutput.includes('Unduh Dokumen (PDF)');
const hasConflictingSignals = isPPTSignal && isPDFSignal;
const hasSupervisorNarration = /(Berikut hasil|Saya akan buatkan|Slide presentasi sudah siap|Laporan Anda sudah siap! Silakan unduh)/i.test(trimmedSupervisor);
const shouldUseDocumentObservation = Boolean(documentObservation) && (( !hasHTML && (isPPTSignal || isPDFSignal)) || (hasHTML && !startsWithDocumentMarkup) || hasConflictingSignals || hasSupervisorNarration);

if (shouldUseDocumentObservation) {
  return [{
    json: {
      ...inputJson,
      output: documentObservation,
      _recovered: true,
    },
  }];
}

return [{ json: inputJson }];

let raw = $input.first().json.output || '';

if (raw.includes('Communication_Agent_response')) {
  const outer = JSON.parse(raw);
  const content = JSON.parse(outer.Communication_Agent_response.content);
  raw = content[0].output;
}

raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();

const draft = JSON.parse(raw);
const originalPrompt = $('Set - Prompt From User').first().json.PromptFinal || '';

const extractEmail = (label) => {
  const escapedLabel = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const match = originalPrompt.match(new RegExp(`${escapedLabel}\\s*:\\s*([^\\n]+)`, 'i'));
  return match?.[1]?.trim() || null;
};

const isReplyRequest = /draft email balasan|balas email|email balasan/i.test(originalPrompt);
const explicitRecipient = extractEmail('Kepada');
const originalSender = extractEmail('Email dari');

if (!draft.to) {
  if (isReplyRequest && originalSender) {
    draft.to = originalSender;
  } else if (explicitRecipient) {
    draft.to = explicitRecipient;
  }
}

const subject = draft.subject || '(tanpa subjek)';
const recipient = draft.to || 'belum ditentukan';
const needsRecipientHint = draft.to ? '' : ' dengan menyebut alamat tujuan jika belum ada';

return [{
  json: {
    output: `Draft email sudah siap.\n\nSubjek: ${subject}\nPenerima: ${recipient}\n\nSilakan review draftnya. Jika sudah sesuai, minta saya kirimkan email ini${needsRecipientHint}.`,
    action_results: {
      email_draft: draft,
    },
  }
}];
